def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_digits(num):
        return sum(int(digit) for digit in str(abs(num)))

    return sum(1 for num in arr if sum_of_digits(num) > 0)

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 
    """
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            # If there were more than 2 spaces before this non-space character, replace them with -
            if space_count > 2:
                result.append('-' * (space_count - 2))
            # Add underscores for each of the current space count
            result.extend(['_' for _ in range(space_count)])
            space_count = 0
            result.append(char)

    # Handle the last group of spaces if they were not replaced yet
    if space_count > 2:
        result.append('-' * (space_count - 2))
    elif space_count == 1:
        result.append('_')

    return ''.join(result)

