def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    total_sum_of_abs_values = 0

    for num in arr:
        if num == 0:
            return 0

        sign_product *= -1 if num < 0 else 1
        total_sum_of_abs_values += abs(num)

    return total_sum_of_abs_values * sign_product

