def max_product(nums):
    # Initialize variables to track the current maximum product and the overall maximum product found so far
    current_max = nums[0]
    global_max = nums[0]

    for num in nums[1:]:
        # If the current number is greater than or equal to the current maximum, update the current maximum to be the current number
        if num >= current_max:
            current_max = num
        else:
            # If the current number is less than the current maximum but greater than or equal to twice the current maximum,
            # update the current maximum to be twice the current maximum plus the current number
            current_max = 2 * current_max + num

        # Update the overall maximum product if the current maximum is greater
        if current_max > global_max:
            global_max = current_max

    return global_max

