def odd_Equivalent(binary_string, rotations):
    # Convert binary string to integer and calculate initial sum of digits
    current_sum = int(binary_string, 2)
    total_odd_sum = 0

    for _ in range(rotations):
        # Calculate new sum of digits after rotation
        current_sum = ((current_sum << 1) + current_sum) % 4

    # Count and return the number of odd sums
    for i in range(total_odd_sum + 1):
