    max_len = 0
    result = []

    # Iterate through each sublist in the main list
    for sub_list in lst:
        # Check if the current sublist's length is greater than the current maximum length
        if len(sub_list) > max_len:
            # Update the maximum length
            max_len = len(sub_list)
            # Reset the result list to include only the current sublist
            result = [sub_list]
        elif len(sub_list) == max_len:
            # If the current sublist's length equals the current maximum length, add it to the result list
            result.append(sub_list)

    return (max_len, result)

def even_binomial_Coeff_Sum(n):
    # Initialize result to 0
    result = 0

    # Calculate sum of even index binomial coefficients
    for i in range(0, n+1, 2):
        result += binomial_coefficient(i, n)

    return result
def binomial_coefficient(n, k):
    # Helper function to calculate binomial coefficient using Pascal's triangle formula
    if k > n - k:
        k = n - k
    coeff = 1
    for i in range(k):
        coeff *= (n-i)
        coeff //= (i+1)
    return coeff

