def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap //= shrink_factor
        if gap <= 1:
            gap = 1
            sorted = True

        for i in range(0, len(arr) - gap, gap):
            if arr[i] > arr[i + gap]:
                # Swap arr[i] and arr[i + gap]
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr

