def catalan_number(n):
    # Initialize an array to store intermediate values of Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1

    for i in range(2, n + 1):
        catalan[i] = 0
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[n]

